INSERT INTO `news` (`id`, `category_id`, `author_id`, `title`, `slug`, `excerpt`, `body`, `body_text`, `cover_media_id`, `status`, `published_at`, `is_featured`, `is_pinned`, `seo_title`, `seo_description`, `canonical_url`, `noindex`, `source_name`, `source_url`, `created_at`, `updated_at`) VALUES
(1, 2, NULL, 'В Госдуме предложили снизить возраст выхода на пенсию для работников сельского хозяйства', 'v-gosdume-predlozhili-snizit-vozrast-vyhoda-na-pensiyu-dlya-rabotnikov-selskogo', 'В Госдуме сегодня рассмотрят законопроект, предлагающий снизить возраст выхода на пенсию для работников агропромышленного комплекса.', '<p>В Госдуме сегодня рассмотрят законопроект, предлагающий снизить возраст выхода на пенсию для работников агропромышленного комплекса.</p>\n<p>Депутаты предлагают разрешить женщинам, работающим в АПК, уходить на пенсию с 55 лет, а мужчинам – с 60 лет.</p>\n<p>Также по мнению депутатов, следует приблизить пенсионные права тружеников села к правам работников органов безопасности, внутренних дел и обороны.</p>\n<p>- Сегодня лишь женщины, проработавшие трактористами-машинистами в сельском хозяйстве, могут уходить на пенсию с 50-летнего возраста. Однако, на наш взгляд, государство должно решить вопрос раннего ухода на пенсию для всех тружеников села. В наше непростое время они постоянно работают над созданием продовольственной безопасности нашей страны", — передают "Известия" слова лидера "Справедливой России" Сергея Миронова.</p>', 'В Госдуме сегодня рассмотрят законопроект, предлагающий снизить возраст выхода на пенсию для работников агропромышленного комплекса. Депутаты предлагают разрешить женщинам, работающим в АПК, уходить на пенсию с 55 лет, а мужчинам – с 60 лет. Также по мнению депутатов, следует приблизить пенсионные права тружеников села к правам работников органов безопасности, внутренних дел и обороны. - Сегодня лишь женщины, проработавшие трактористами-машинистами в сельском хозяйстве, могут уходить на пенсию с 50-летнего возраста. Однако, на наш взгляд, государство должно решить вопрос раннего ухода на пенсию для всех тружеников села. В наше непростое время они постоянно работают над созданием продовольственной безопасности нашей страны", — передают "Известия" слова лидера "Справедливой России" Сергея Миронова.', NULL, 'published', '2024-10-23 11:00:00', 0, 0, NULL, NULL, NULL, 0, NULL, NULL, '2024-10-23 11:00:00', '2024-10-23 11:00:00'),
(2, 1, NULL, 'Кореновские малыши создают волшебные миры из песка', 'korenovskie-malyshi-sozdayut-volshebnye-miry-iz-peska', 'Вот уже больше шести месяцев малыши и их мамы занимаются в группах песочной терапии на базе АНО социальный Центр семейного развития "Обыкновенное чудо".', '<p>Вот уже больше шести месяцев малыши и их мамы занимаются в группах песочной терапии на базе АНО социальный Центр семейного развития "Обыкновенное чудо".</p>\n<p>Восемнадцать семей с детьми в возрасте от 3 до 6 лет имеют возможность бесплатно посещать развивающие занятия с песком, благодаря поддержке гранта губернатора Кубани и администрации района.</p>\n<p>Под руководством психолога малыши учатся работать за световым песочным столом и выполнять задания, показанные на экране, что, несомненно, пригодится в школе. А играя вместе со своими мамами с кинетическим или обычным песком, создают собственные волшебные миры, что позитивно влияет на внутрисемейные отношения.</p>\n<p>Игры с песком способствуют развитию мелкой моторики, усидчивости и воображения. Работа с мягким, сыпучим материалом успокаивает, снижает тревожность, помогает справиться с гиперактивностью и невнимательностью. А интересные задания психолога в игровой форме позволяют улучшить концентрацию внимания и развить способность к обучению.</p>\n<p>Занятия проводятся каждую неделю, и малыши всегда с нетерпением и удовольствием спешат на "Песочную сказку".</p>', 'Вот уже больше шести месяцев малыши и их мамы занимаются в группах песочной терапии на базе АНО социальный Центр семейного развития "Обыкновенное чудо". Восемнадцать семей с детьми в возрасте от 3 до 6 лет имеют возможность бесплатно посещать развивающие занятия с песком, благодаря поддержке гранта губернатора Кубани и администрации района. Под руководством психолога малыши учатся работать за световым песочным столом и выполнять задания, показанные на экране, что, несомненно, пригодится в школе. А играя вместе со своими мамами с кинетическим или обычным песком, создают собственные волшебные миры, что позитивно влияет на внутрисемейные отношения. Игры с песком способствуют развитию мелкой моторики, усидчивости и воображения. Работа с мягким, сыпучим материалом успокаивает, снижает тревожность, помогает справиться с гиперактивностью и невнимательностью. А интересные задания психолога в игровой форме позволяют улучшить концентрацию внимания и развить способность к обучению. Занятия проводятся каждую неделю, и малыши всегда с нетерпением и удовольствием спешат на "Песочную сказку".', 1, 'published', '2024-10-23 15:30:00', 0, 0, NULL, NULL, NULL, 0, NULL, NULL, '2024-10-23 15:30:00', '2024-10-23 15:30:00'),
(3, 3, NULL, 'На Кубани провели второй этап профилактической акции «Сообщи, где торгуют смертью!»', 'na-kubani-proveli-vtoroy-etap-profilakticheskoy-akcii-soobschi-gde-torguyut', 'Молодой депутат Кореновского района Андрей Деменко вместе со специалистом по работе с молодежью Алиной Слинько, сотрудником Дома культуры поселка Новоберезанского Натальей Кордюковой и…', '<p>Молодой депутат Кореновского района Андрей Деменко вместе со специалистом по работе с молодежью Алиной Слинько, сотрудником Дома культуры поселка Новоберезанского Натальей Кордюковой и старшеклассниками школы №15 провели на территории поселка второй этап профилактической антинаркотической акции «Сообщи, где торгуют смертью!».</p>\n<p>В ходе акции парламентарий и молодежные активисты распространили листовки с призывами к гражданам не быть равнодушными и незамедлительно сообщать в ответственные службы обо всех случаях изготовления, хранения, распространения и употребления запрещенных законом веществ.</p>', 'Молодой депутат Кореновского района Андрей Деменко вместе со специалистом по работе с молодежью Алиной Слинько, сотрудником Дома культуры поселка Новоберезанского Натальей Кордюковой и старшеклассниками школы №15 провели на территории поселка второй этап профилактической антинаркотической акции «Сообщи, где торгуют смертью!». В ходе акции парламентарий и молодежные активисты распространили листовки с призывами к гражданам не быть равнодушными и незамедлительно сообщать в ответственные службы обо всех случаях изготовления, хранения, распространения и употребления запрещенных законом веществ.', 2, 'published', '2024-10-24 10:00:00', 0, 0, NULL, NULL, NULL, 0, NULL, NULL, '2024-10-24 10:00:00', '2024-10-24 10:00:00'),
(4, 1, NULL, 'В Кореновском районе поддержали социальные категории граждан', 'v-korenovskom-rayone-podderzhali-socialnye-kategorii-grazhdan', 'Молодые депутаты Кореновского района провели очередную благотворительную акцию «По зову сердца!», направленную на поддержку социальных категорий граждан.', '<p>Молодые депутаты Кореновского района провели очередную благотворительную акцию «По зову сердца!», направленную на поддержку социальных категорий граждан.</p>\n<p>Заместитель председателя СМД Ольга Ляховенко, молодые депутаты Анна Тарасова и Ольга Захарова адресно доставили наборы детских и взрослых вещей трем семьям из станиц Журавской и Раздольной, нуждающимся в поддержке общества.</p>\n<p>Вещи были собраны парламентариями при участии неравнодушных жителей района, откликнувшихся на призыв молодых депутатов сделать общее доброе дело.</p>', 'Молодые депутаты Кореновского района провели очередную благотворительную акцию «По зову сердца!», направленную на поддержку социальных категорий граждан. Заместитель председателя СМД Ольга Ляховенко, молодые депутаты Анна Тарасова и Ольга Захарова адресно доставили наборы детских и взрослых вещей трем семьям из станиц Журавской и Раздольной, нуждающимся в поддержке общества. Вещи были собраны парламентариями при участии неравнодушных жителей района, откликнувшихся на призыв молодых депутатов сделать общее доброе дело.', 3, 'published', '2024-10-24 12:00:00', 0, 0, NULL, NULL, NULL, 0, NULL, NULL, '2024-10-24 12:00:00', '2024-10-24 12:00:00'),
(5, 4, NULL, 'Магнитная буря внезапно начнется 25 октября в Краснодарском крае', 'magnitnaya-burya-vnezapno-nachnetsya-25-oktyabrya-v-krasnodarskom-krae', 'Жителей Краснодарского края предупредили о кратковременной магнитной буре в конце недели, подробности рассказали в Лаборатории солнечной астрономии РАН.', '<h3>Жителей Краснодарского края предупредили о кратковременной магнитной буре в конце недели, подробности рассказали в Лаборатории солнечной астрономии РАН.</h3>\n<p>Специалисты лаборатории сообщили о всплеске магнитной активности в первой половине дня 25 октября. Буря достигнет четырех баллов и будет стремиться к отметке слабой магнитной бури G1. Буря закончится так же быстро, как и начнется — около четырех часов. Буря начнется около 08:00 мск и закончится к 12:00. На остаток дня пятницы 25 и в субботу 26 октября магнитное поле будет спокойным.</p>\n<p>Однако ученые зафиксировали вспышку на Солнце класса X. Это произошло 24 октября. Есть вероятность того, что к середине дня субботы, 26 октября, Кубань вновь может накрыть магнитная буря. Прогноз уточняется.</p>\n<p>На изображении с сайта Лаборатории можно увидеть процесс выброса массы с поверхности Солнца в сторону Земли.</p>\n<p><i>Буря негативно влияет на состояние здоровья метеозависимых людей.</i> Ранее KubanPress писала о <a href="https://kubanpress.ru/news/2024-10-11/severnoe-siyanie-poyavilos-nad-chernym-morem-na-kubani-iz-za-moschnoy-magnitnoy-buri-5218716" rel="noopener" target="_blank">северном сиянии</a> в южных широтах Краснодарского края из-за магнитной бури.</p>', 'Жителей Краснодарского края предупредили о кратковременной магнитной буре в конце недели, подробности рассказали в Лаборатории солнечной астрономии РАН. Специалисты лаборатории сообщили о всплеске магнитной активности в первой половине дня 25 октября. Буря достигнет четырех баллов и будет стремиться к отметке слабой магнитной бури G1. Буря закончится так же быстро, как и начнется — около четырех часов. Буря начнется около 08:00 мск и закончится к 12:00. На остаток дня пятницы 25 и в субботу 26 октября магнитное поле будет спокойным. Однако ученые зафиксировали вспышку на Солнце класса X. Это произошло 24 октября. Есть вероятность того, что к середине дня субботы, 26 октября, Кубань вновь может накрыть магнитная буря. Прогноз уточняется. На изображении с сайта Лаборатории можно увидеть процесс выброса массы с поверхности Солнца в сторону Земли. Буря негативно влияет на состояние здоровья метеозависимых людей. Ранее KubanPress писала о северном сиянии в южных широтах Краснодарского края из-за магнитной бури.', 4, 'published', '2024-10-24 17:00:00', 0, 0, NULL, NULL, NULL, 0, NULL, NULL, '2024-10-24 17:00:00', '2024-10-24 17:00:00'),
(6, 2, NULL, 'Передовиков на Дне урожая наградили губернатор Кубани Вениамин Кондратьев вместе с полпредом Президента России в ЮФО Владимиром Устиновым', 'peredovikov-na-dne-urozhaya-nagradili-gubernator-kubani-veniamin-kondratev', 'Отмечены сегодня и кореновцы. Медаль ордена "За заслуги перед Отечеством" ll степени вручили Виктору Фоменко, слесарю-инструментальщику механического цеха АО "Кореновсксахар".', '<p>Отмечены сегодня и кореновцы. Медаль ордена "За заслуги перед Отечеством" ll степени вручили Виктору Фоменко, слесарю-инструментальщику механического цеха АО "Кореновсксахар".</p>\n<p>Почетное звание "Заслуженный работник сельского хозяйства Российской Федерации" присвоили Любови Рутенко, агроному ООО "Раздольное" и Вячеславу Щукину, трактористу-машинисту с/х производства ООО "Родина".</p>\n<p>Поздравляя аграриев-передовиков, губернатор отметил, что с такими людьми Кубань и впредь будет оставаться гарантом продовольственной безопасности России.</p>', 'Отмечены сегодня и кореновцы. Медаль ордена "За заслуги перед Отечеством" ll степени вручили Виктору Фоменко, слесарю-инструментальщику механического цеха АО "Кореновсксахар". Почетное звание "Заслуженный работник сельского хозяйства Российской Федерации" присвоили Любови Рутенко, агроному ООО "Раздольное" и Вячеславу Щукину, трактористу-машинисту с/х производства ООО "Родина". Поздравляя аграриев-передовиков, губернатор отметил, что с такими людьми Кубань и впредь будет оставаться гарантом продовольственной безопасности России.', 6, 'published', '2024-10-27 10:00:00', 0, 0, NULL, NULL, NULL, 0, NULL, NULL, '2024-10-27 10:00:00', '2024-10-27 10:00:00'),
(7, 5, NULL, 'Юбилейный, 10 межрегиональный турнир по футболу среди ветеранов доказал, что и у нас есть мастера мяча высшего класса!', 'yubileynyy-10-mezhregionalnyy-turnir-po-futbolu-sredi-veteranov-dokazal-chto-i', 'Турнир проходил с марта по июнь этого года. А подведение его итогов приурочили к открытию новой серии игр "Золотая осень".', '<p>Турнир проходил с марта по июнь этого года. А подведение его итогов приурочили к открытию новой серии игр "Золотая осень".</p>\n<p>На центральном стадионе сегодня наградили команды-победительницы весеннего Кубка.</p>\n<p>Участие в играх принимали команды Армавира, Усть-Лабинска, Тихорецка, Кореновска и Выселок.</p>\n<p><b><i> 1. Золото соревнований в итоге забрали наши футболисты! <br> 2. Серебро у выселковцев! <br> 3. Почётная бронза у команды из Усть-Лабинска! </i></b></p>\n<p>Поздравляем победителей! И желаем осеннему турниру столь же сильных эмоций!</p>', 'Турнир проходил с марта по июнь этого года. А подведение его итогов приурочили к открытию новой серии игр "Золотая осень". На центральном стадионе сегодня наградили команды-победительницы весеннего Кубка. Участие в играх принимали команды Армавира, Усть-Лабинска, Тихорецка, Кореновска и Выселок. 1. Золото соревнований в итоге забрали наши футболисты! 2. Серебро у выселковцев! 3. Почётная бронза у команды из Усть-Лабинска! Поздравляем победителей! И желаем осеннему турниру столь же сильных эмоций!', 14, 'published', '2024-10-27 11:00:00', 0, 0, NULL, NULL, NULL, 0, NULL, NULL, '2024-10-27 11:00:00', '2024-10-27 11:00:00'),
(8, 6, NULL, 'Крестный ход с иконой Пресвятой Богородицы «Избавительница от бед» в Кореновском районе', 'krestnyy-hod-s-ikonoy-presvyatoy-bogorodicy-izbavitelnica-ot-bed-v-korenovskom', 'С 31 октября по 4 ноября по храмам Кореновского благочиния с благословения Стефана, епископа Тихорецкого и Кореновского, пройдет крестный ход с иконой Пресвятой Богородицы «Избавительница от бед».', '<p>С 31 октября по 4 ноября по храмам Кореновского благочиния с благословения Стефана, епископа Тихорецкого и Кореновского, пройдет крестный ход с иконой Пресвятой Богородицы «Избавительница от бед».</p>\n<p>График пребывания образа Пресвятой Богородицы «Избавительница от бед» в Кореновском благочинии: <br> <b><i> <br>1. 31 октября, четверг, 14-00: пос. Комсомольский, храм иконы Божией Матери «Спорительница хлебов», <br>2. 31 октября, четверг, 16-00: г. Кореновск, Свято-Успенский женский Епархиальный монастырь, <br>3. 1 ноября, пятница, 10-00: ст. Дядьковская, храм Покрова Пресвятой Богородицы, <br>4. 1 ноября, пятница, 12-00: с. Братковское, храм Казанской иконы Божией Матери, <br>5. 1 ноября, пятница, 14-30: ст. Сергиевская, храм Сергия Радонежского, <br>6. 1 ноября, пятница, 16-30: ст. Платнировская, храм Троицы Живоначальной, <br>7. 2 ноября, суббота, 11-30: г. Кореновск, храм Смоленской иконы Божией Матери, <br>8. 2 ноября, суббота, 14-00: г. Кореновск, Свято-Владимирский храм, <br>9. 3 ноября, воскресенье, 11-00: г. Кореновск, храм святых Новомучеников Кубанских, <br>10. 3 ноября, воскресенье, 13-30: х. Бураковский, храм святых Петра и Февронии, <br>11. 3 ноября, воскресенье, 16-00: г. Кореновск, храм Саввы Освященного, <br>12. 4 ноября, понедельник, 11-00: ст. Раздольная, храм Вознесения Господня, 13. 4 ноября, понедельник, 13-30: ст. Журавская, храм святой мученицы Татианы. </i></b></p>', 'С 31 октября по 4 ноября по храмам Кореновского благочиния с благословения Стефана, епископа Тихорецкого и Кореновского, пройдет крестный ход с иконой Пресвятой Богородицы «Избавительница от бед». График пребывания образа Пресвятой Богородицы «Избавительница от бед» в Кореновском благочинии: 1. 31 октября, четверг, 14-00: пос. Комсомольский, храм иконы Божией Матери «Спорительница хлебов», 2. 31 октября, четверг, 16-00: г. Кореновск, Свято-Успенский женский Епархиальный монастырь, 3. 1 ноября, пятница, 10-00: ст. Дядьковская, храм Покрова Пресвятой Богородицы, 4. 1 ноября, пятница, 12-00: с. Братковское, храм Казанской иконы Божией Матери, 5. 1 ноября, пятница, 14-30: ст. Сергиевская, храм Сергия Радонежского, 6. 1 ноября, пятница, 16-30: ст. Платнировская, храм Троицы Живоначальной, 7. 2 ноября, суббота, 11-30: г. Кореновск, храм Смоленской иконы Божией Матери, 8. 2 ноября, суббота, 14-00: г. Кореновск, Свято-Владимирский храм, 9. 3 ноября, воскресенье, 11-00: г. Кореновск, храм святых Новомучеников Кубанских, 10. 3 ноября, воскресенье, 13-30: х. Бураковский, храм святых Петра и Февронии, 11. 3 ноября, воскресенье, 16-00: г. Кореновск, храм Саввы Освященного, 12. 4 ноября, понедельник, 11-00: ст. Раздольная, храм Вознесения Господня, 13. 4 ноября, понедельник, 13-30: ст. Журавская, храм святой мученицы Татианы.', 24, 'published', '2024-10-27 12:00:00', 0, 0, NULL, NULL, NULL, 0, NULL, NULL, '2024-10-27 12:00:00', '2024-10-27 12:00:00'),
(9, 7, NULL, 'Многолетние цветы на клумбе перед ЖД вокзалом', 'mnogoletnie-cvety-na-klumbe-pered-zhd-vokzalom', 'Центр озеленения высадил многолетние цветы на клумбе перед ЖД вокзалом Кореновска. Фото: Максим Шутылев', '<p>Центр озеленения высадил многолетние цветы на клумбе перед ЖД вокзалом Кореновска.</p>\n<p><i>Фото: Максим Шутылев</i></p>', 'Центр озеленения высадил многолетние цветы на клумбе перед ЖД вокзалом Кореновска. Фото: Максим Шутылев', 25, 'published', '2024-10-27 09:00:00', 0, 0, NULL, NULL, NULL, 0, NULL, NULL, '2024-10-27 09:00:00', '2024-10-27 09:00:00'),
(10, 8, NULL, 'Гороскоп на неделю с 28 октября по 3 ноября от Тамары Ло', 'goroskop-na-nedelyu-s-28-oktyabrya-po-3-noyabrya-ot-tamary-lo', 'В понедельник потребуется уделить внимание личным вещам, финансам и сохранению жилья.', '<p>В понедельник потребуется уделить внимание личным вещам, финансам и сохранению жилья. Во вторник будьте деликатны с теми, кого любите, и старайтесь избегать конфликтов. В среду откажитесь от любых споров. В четверг в атмосфере может возникнуть напряжение, поэтому сохраняйте контроль над своими эмоциями. В пятницу визуализируйте свои мечты и планируйте будущее. В субботу занимайтесь простой работой, не требующей особой ответственности. Воскресенье В воскресенье уделите время физической активности и отдыху.</p>\n<h3>Овен</h3>\n<p>На этой неделе Овны смогут расслабиться, но впереди их ждет ответственный период с напряженной работой и решением сложных задач. Занимайтесь текущими делами, радуйтесь тому, что имеете, и проводите время с близкими. Создайте теплую атмосферу в семье.</p>\n<h3>Телец</h3>\n<p>На этой неделе не все будет получаться так, как хотелось бы, но это не повод для огорчений. Работайте в меру своих возможностей и не стремитесь прыгнуть выше головы. Некоторые Тельцы решат вернуться к прежним делам — это правильное решение.</p>\n<h3>Близнецы</h3>\n<p>Вам предстоит получить разнообразную информацию, среди которой будет что-то важное. Не спешите с решениями — лучше хорошенько обдумайте все. На работе могут возникнуть конфликты в коллективе; старайтесь избегать их, чтобы не усложнять себе жизнь.</p>\n<h3>Рак</h3>\n<p>Это удачная неделя для начала новых проектов. Начинайте их без лишней саморекламы — лучше избегать внимания со стороны окружающих. Лучшее место для восстановления сил — это ваш дом и семья. Проводите больше времени с близкими.</p>\n<h3>Лев</h3>\n<p>Неделя будет удачной для самых разных дел. Молодые Львы будут успешны в любви и флирте. Некоторые Львы подумают о смене работы или нового направления деятельности. Переговоры будут успешными — вы выглядите убедительно и аргументированно.</p>\n<h3>Дева</h3>\n<p>Используйте энергетику этой недели для профессионального роста и личной жизни. Некоторые Девы могут рассмотреть возможность повышения квалификации — соглашайтесь на такие предложения. Не забывайте уделять время семье; сейчас отличные дни для укрепления отношений.</p>\n<h3>Весы</h3>\n<p>На этой неделе вам будет легко справляться со сложными задачами. Некоторые из вас могут получить повышение на работе или увеличение зарплаты. Старайтесь поддерживать стабильное положение и больше отдыхайте. Если вы давно не были в отпуске, сейчас самое время отправиться в путешествие.</p>\n<h3>Скорпион</h3>\n<p>Следите за своими финансами — возможно, вам потребуется дополнительный заработок. Новые знакомства и деловые связи могут оказаться перспективными. Не забывайте о других сферах жизни, где вас тоже ждут и рассчитывают на вас.</p>\n<h3>Стрелец</h3>\n<p>На работе вы будете думать о личной жизни — это касается особенно молодых и одиноких Стрельцов. Если вы недавно познакомились с кем-то, внимательно присматривайтесь к отношениям; есть шанс сохранить их надолго. Если есть возможность выехать на выходные за город, воспользуйтесь ею — это пойдет вам на пользу.</p>\n<h3>Козерог</h3>\n<p>Неделя обещает быть продуктивной с самого начала. Наметьте все важные дела и смело приступайте к их выполнению. Уверенно встречайтесь с деловыми партнерами — вы будете убедительны, особенно если заранее подготовите аргументы. Ваши близкие оценят внимание и сюрпризы от вас; постарайтесь провести вместе конец недели.</p>\n<h3>Водолей</h3>\n<p>К вам вернулся энтузиазм, появились силы и энергия для решения сложных вопросов. Вы даже сможете поддерживать других. Не бойтесь брать на себя больше ответственности; вы видите перспективу и предчувствуете положительный результат.</p>\n<h3>Рыбы</h3>\n<p>Количество встреч и контактов у Рыб может увеличиться из-за активности в деловой и дружеской сферах. Вы легко найдете выход из сложных ситуаций и поддержите тех, кто нуждается в помощи. Следите за своей речью, чтобы ненароком никого не обидеть, и не забывайте уделять время семье. Надеюсь, этот вариант вам понравится!</p>', 'В понедельник потребуется уделить внимание личным вещам, финансам и сохранению жилья. Во вторник будьте деликатны с теми, кого любите, и старайтесь избегать конфликтов. В среду откажитесь от любых споров. В четверг в атмосфере может возникнуть напряжение, поэтому сохраняйте контроль над своими эмоциями. В пятницу визуализируйте свои мечты и планируйте будущее. В субботу занимайтесь простой работой, не требующей особой ответственности. Воскресенье В воскресенье уделите время физической активности и отдыху. Овен На этой неделе Овны смогут расслабиться, но впереди их ждет ответственный период с напряженной работой и решением сложных задач. Занимайтесь текущими делами, радуйтесь тому, что имеете, и проводите время с близкими. Создайте теплую атмосферу в семье. Телец На этой неделе не все будет получаться так, как хотелось бы, но это не повод для огорчений. Работайте в меру своих возможностей и не стремитесь прыгнуть выше головы. Некоторые Тельцы решат вернуться к прежним делам — это правильное решение. Близнецы Вам предстоит получить разнообразную информацию, среди которой будет что-то важное. Не спешите с решениями — лучше хорошенько обдумайте все. На работе могут возникнуть конфликты в коллективе; старайтесь избегать их, чтобы не усложнять себе жизнь. Рак Это удачная неделя для начала новых проектов. Начинайте их без лишней саморекламы — лучше избегать внимания со стороны окружающих. Лучшее место для восстановления сил — это ваш дом и семья. Проводите больше времени с близкими. Лев Неделя будет удачной для самых разных дел. Молодые Львы будут успешны в любви и флирте. Некоторые Львы подумают о смене работы или нового направления деятельности. Переговоры будут успешными — вы выглядите убедительно и аргументированно. Дева Используйте энергетику этой недели для профессионального роста и личной жизни. Некоторые Девы могут рассмотреть возможность повышения квалификации — соглашайтесь на такие предложения. Не забывайте уделять время семье; сейчас отличные дни для укрепления отношений. Весы На этой неделе вам будет легко справляться со сложными задачами. Некоторые из вас могут получить повышение на работе или увеличение зарплаты. Старайтесь поддерживать стабильное положение и больше отдыхайте. Если вы давно не были в отпуске, сейчас самое время отправиться в путешествие. Скорпион Следите за своими финансами — возможно, вам потребуется дополнительный заработок. Новые знакомства и деловые связи могут оказаться перспективными. Не забывайте о других сферах жизни, где вас тоже ждут и рассчитывают на вас. Стрелец На работе вы будете думать о личной жизни — это касается особенно молодых и одиноких Стрельцов. Если вы недавно познакомились с кем-то, внимательно присматривайтесь к отношениям; есть шанс сохранить их надолго. Если есть возможность выехать на выходные за город, воспользуйтесь ею — это пойдет вам на пользу. Козерог Неделя обещает быть продуктивной с самого начала. Наметьте все важные дела и смело приступайте к их выполнению. Уверенно встречайтесь с деловыми партнерами — вы будете убедительны, особенно если заранее подготовите аргументы. Ваши близкие оценят внимание и сюрпризы от вас; постарайтесь провести вместе конец недели. Водолей К вам вернулся энтузиазм, появились силы и энергия для решения сложных вопросов. Вы даже сможете поддерживать других. Не бойтесь брать на себя больше ответственности; вы видите перспективу и предчувствуете положительный результат. Рыбы Количество встреч и контактов у Рыб может увеличиться из-за активности в деловой и дружеской сферах. Вы легко найдете выход из сложных ситуаций и поддержите тех, кто нуждается в помощи. Следите за своей речью, чтобы ненароком никого не обидеть, и не забывайте уделять время семье. Надеюсь, этот вариант вам понравится!', 30, 'published', '2024-10-27 08:00:00', 0, 0, NULL, NULL, NULL, 0, NULL, NULL, '2024-10-27 08:00:00', '2024-10-27 08:00:00'),
(11, 4, NULL, 'Дожди доберутся до Краснодарского края', 'dozhdi-doberutsya-do-krasnodarskogo-kraya', 'Несмотря на осадки, в нашем регионе до конца октября всё ещё будет тепло!', '<p>Несмотря на осадки, в нашем регионе до конца октября всё ещё будет тепло! 🌤️ Термометры покажут до +18 градусов.</p>\n<p>Дожди ожидаются на Кубани в ближайшие дни, однако они не будут экстремальными и пройдут местами, не влияя на температуру. До середины недели в дневное время температура будет колебаться от +13 до +18 градусов, а ночи станут немного теплее.</p>\n<p>По данным Краснодарского гидрометцентра:</p>\n<p>- 29 октября: Ночью +5 до +10°С, в юго-восточной части – от +4 до -1°. Днём – +13 до +18°. В утренние часы есть вероятность тумана, а также начнутся дожди – от слабого до умеренного.</p>\n<p>- 30 октября: Ночью +5 до +10°, в предгорьях – от +4 до -1°. Днём – +13 до +18°. Вероятны туманы и дожди, в горах возможен мокрый снег.</p>\n<p>- 31 октября: Ночью +3 до +8°, днём +13 до +18°. Ожидается пасмурная и дождливая погода. Скорость западного ветра при порывах составит 12-14 м/с, в отдельных районах – до 18 м/с.</p>\n<p><b>Берегите себя и будьте готовы к изменениям погоды! ☔</b></p>', 'Несмотря на осадки, в нашем регионе до конца октября всё ещё будет тепло! 🌤️ Термометры покажут до +18 градусов. Дожди ожидаются на Кубани в ближайшие дни, однако они не будут экстремальными и пройдут местами, не влияя на температуру. До середины недели в дневное время температура будет колебаться от +13 до +18 градусов, а ночи станут немного теплее. По данным Краснодарского гидрометцентра: - 29 октября: Ночью +5 до +10°С, в юго-восточной части – от +4 до -1°. Днём – +13 до +18°. В утренние часы есть вероятность тумана, а также начнутся дожди – от слабого до умеренного. - 30 октября: Ночью +5 до +10°, в предгорьях – от +4 до -1°. Днём – +13 до +18°. Вероятны туманы и дожди, в горах возможен мокрый снег. - 31 октября: Ночью +3 до +8°, днём +13 до +18°. Ожидается пасмурная и дождливая погода. Скорость западного ветра при порывах составит 12-14 м/с, в отдельных районах – до 18 м/с. Берегите себя и будьте готовы к изменениям погоды! ☔', 31, 'published', '2024-10-28 09:00:00', 1, 0, NULL, NULL, NULL, 0, NULL, NULL, '2024-10-28 09:00:00', '2024-10-28 09:00:00');
